(()=>{function sync(){if(typeof dashboard==='undefined'||!dashboard?.company)return false;window.dashboard=dashboard;const roles=dashboard.company.capabilities||[],role=roles.includes('contractor')&&roles.includes('subcontractor')?'Contractor & Subcontractor':roles.includes('contractor')?'Contractor':'Subcontractor',profileTitle=roles.includes('contractor')&&roles.includes('subcontractor')?'Contractor & Subcontractor Profile':roles.includes('contractor')?'Contractor Profile':'Subcontractor Profile';const badge=document.getElementById('navRole'),profileNav=document.querySelector('[data-view="profile"]');if(badge)badge.textContent=role;if(profileNav)profileNav.textContent=profileTitle;return true}if(!sync()){const timer=setInterval(()=>{if(sync())clearInterval(timer)},100);setTimeout(()=>clearInterval(timer),20000)}})();
